(p/'showcase.js').write_text('''let toastTimer;function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3000)}document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('Cor copiada: '+b.dataset.copy)}catch{toast('Cor: '+b.dataset.copy)}});document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>toast(b.dataset.demo));const tabs=[...document.querySelectorAll('[role=tab]')];function selectTab(tab){tabs.forEach(b=>{b.setAttribute('aria-selected',String(b===tab));b.tabIndex=b===tab?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=b!==tab})}tabs.forEach((b,i)=>{b.onclick=()=>selectTab(b);b.onkeydown=e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();selectTab(tabs[n]);tabs[n].focus()}}});document.querySelector('#loading').onclick=async function(){this.disabled=true;this.setAttribute('aria-busy','true');this.textContent='Saving…';setTimeout(()=>{this.disabled=false;this.removeAttribute('aria-busy');this.textContent='Try loading state';toast('Demonstração concluída. Nenhum dado foi enviado.')},1200)};const form=document.querySelector('#demo-form'),email=document.querySelector('#email'),err=document.querySelector('#email-error');form.onsubmit=e=>{e.preventDefault();const valid=email.validity.valid;email.setAttribute('aria-invalid',String(!valid));err.hidden=valid;err.textContent=valid?'':'Enter a valid email address, such as you@example.com.';document.querySelector('#form-result').textContent=valid?'✓ Looks good. This demo did not send or store your email.':'';if(!valid)email.focus()};email.oninput=()=>{email.removeAttribute('aria-invalid');err.hidden=true;document.querySelector('#form-result').textContent=''};document.querySelector('#progress-action').onclick=function(){let p=document.querySelector('#demo-progress');p.value=p.value===6?0:p.value+1;document.querySelector('#progress-label').textContent=p.value+' of 6';this.textContent=p.value===6?'Reset demo progress':'Complete a demo week';};''')
(p/'components.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UpNext Care component starter</title><link rel="stylesheet" href="upnext.css"></head><body class="un"><main class="un-wrap" style="padding-block:48px;max-width:700px"><h1>Your next small step.</h1><article class="un-card"><span class="un-badge">Week 1 of 6</span><h2>Healthy Routines</h2><p>Make room for habits that fit your life.</p><progress class="un-progress" max="6" value="1" aria-label="1 of 6 weeks completed"></progress><a class="un-button" href="/learn/">Continue learning →</a></article><section style="margin-top:32px"><label class="un-label" for="reflection">Your reflection</label><textarea id="reflection" class="un-input" rows="4" aria-describedby="reflection-help"></textarea><span id="reflection-help" class="un-help">Connect this field to your application before enabling saving.</span><button class="un-button" disabled style="margin-top:16px">Save unavailable in starter</button></section></main></body></html>''')
(p/'README.txt').write_text('''UPNEXT CARE DESIGN SYSTEM v1.0

Purpose: a calm, warm, optimistic identity for UpNext Care.
Files: upnext.css (shared tokens and components), tokens.json (portable design values), components.html (starter), index.html and showcase.js (interactive documentation).

Install: import upnext.css once in the shared layout. Put class="un" on the app container. The stylesheet includes a global box-sizing reset; audit existing CSS for conflicts before adoption. Component classes use the un- prefix. No build or external font required. Inter is used if locally installed; otherwise system UI. Display typography uses Georgia.

Do not import showcase.js into the product: it contains demonstration interactions only. Connect real forms and controls to the existing application logic. Translate interface text as a complete flow. English is the product default, with pt-BR and es variants.

Color roles: Forest primary action; Ink text; Cream canvas; Paper surface; Sage support/progress; Lilac reflection; Peach prevention/support. Soft colors are backgrounds, not body text. Use Ink text on soft colors and Paper text on Forest. Check every new combination for 4.5:1 normal-text contrast. Error #A13232, warning #785314, info #325A81. Status always includes text.

Spacing: 4,8,12,16,24,32,48,64,96px. Radius:8px fields,16px panels,24px cards,full for buttons/badges. Content max1160px; 24px desktop gutters and16px mobile. Body16px line-height1.6; labels14px; helper13px. H1 48–80px, H2 32–48px. Allow text expansion in translations.

Accessibility: semantic headings, visible focus, persistent labels, field error associations, keyboard operation, 48px touch controls, reduced motion. Use status/alert live regions for dynamic success/error. Program progress uses native progress with accessible label. Tables accompany charts. No-data must not be rendered as zero. Validate mobile layout and 200% zoom when integrating.

Brand mark in showcase is a visual proposal, not an automatically adopted replacement logo. Example copy and progress are demonstration data. No medical outcomes are implied.

Adoption: integrate tokens; migrate shared buttons/forms/cards; migrate one low-risk page; check responsive layouts, translations, focus, validation and existing behavior; then apply consistently to courses and result views. Existing main site is not modified by this package.

Governance: update tokens, CSS and this reference together. Add components when repeated patterns exist. Version breaking changes separately. No Figma dependency.
''')
